//! The streams the sweep codes. Law streams are generated by the kernel's own
//! operations with a noise rate `eps` (the share of symbols replaced by
//! uniform noise), so every QL prior is tested where it holds, where it
//! partly holds and where it fails. Two streams are real: the kernel's
//! recorded M3 clock and this repository's documentation text.
use std::path::Path;

use ql_core::{MatrixFamily, generate, m3_clock};

use crate::codecs::{KernelOp, lens_scales};

/// Deterministic splitmix64; seeds are fixed per stream.
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Self {
        Self(seed)
    }

    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    pub fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }

    pub fn chance(&mut self, p: f64) -> bool {
        ((self.next_u64() >> 11) as f64 / (1u64 << 53) as f64) < p
    }

    pub fn weighted(&mut self, weights: &[u64]) -> usize {
        let mut pick = self.below(weights.iter().sum());
        for (i, w) in weights.iter().enumerate() {
            if pick < *w {
                return i;
            }
            pick -= w;
        }
        weights.len() - 1
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// Positive/negative codon pairs of generation cells (alphabet 64).
    GenerationPairs,
    /// Hexagram ids (alphabet 64).
    Hexagrams,
    /// Pitch classes (alphabet 12).
    Pitches,
    /// Raw bytes (alphabet 256).
    Bytes,
}

pub struct Stream {
    pub name: String,
    pub kind: Kind,
    pub alphabet: usize,
    pub eps: f64,
    pub symbols: Vec<u16>,
    /// The unit bits are counted per: one symbol, or one source byte for text.
    pub units: usize,
}

impl Stream {
    /// One byte per symbol, for the general-purpose compressors.
    pub fn bytes(&self) -> Vec<u8> {
        self.symbols.iter().map(|s| *s as u8).collect()
    }
}

fn seed(name: &str, n: usize, eps: f64) -> u64 {
    name.bytes().fold(n as u64 ^ eps.to_bits(), |h, b| {
        h.wrapping_mul(0x100_0000_01B3) ^ u64::from(b)
    })
}

/// A cast hexagram moves each line with probability 1/4 (two of the eight
/// coin outcomes per line are old yin / old yang).
fn cast(rng: &mut Rng, hexagram: u8) -> u8 {
    (0..6).fold(
        hexagram,
        |h, line| {
            if rng.chance(0.25) { h ^ (1 << line) } else { h }
        },
    )
}

/// QLC-1 source: a cast hexagram walk read through a matrix that changes
/// rarely; each cell emits its positive then its negative codon.
pub fn generation_pairs(pairs: usize, eps: f64) -> Stream {
    let mut rng = Rng::new(seed("generation-pairs", pairs, eps));
    let mut hexagram = rng.below(64) as u8;
    let mut matrix = 0usize;
    let mut symbols = Vec::with_capacity(pairs * 2);
    for _ in 0..pairs {
        hexagram = cast(&mut rng, hexagram);
        if rng.chance(1.0 / 64.0) {
            matrix = rng.below(3) as usize;
        }
        let cell = generate(MatrixFamily::ALL[matrix], hexagram);
        symbols.push(u16::from(cell.positive.address()));
        symbols.push(if rng.chance(eps) {
            rng.below(64) as u16
        } else {
            u16::from(cell.negative.address())
        });
    }
    let units = symbols.len();
    Stream {
        name: "generation-pairs".into(),
        kind: Kind::GenerationPairs,
        alphabet: 64,
        eps,
        symbols,
        units,
    }
}

/// QLC-3 source: hexagrams moved by kernel operators drawn with fixed,
/// uneven weights (line changes favour the lower lines).
pub fn operator_walk(n: usize, eps: f64) -> Stream {
    let mut rng = Rng::new(seed("operator-walk", n, eps));
    let ops = KernelOp::all();
    let weights: Vec<u64> = ops
        .iter()
        .map(|op| match op {
            KernelOp::Identity => 6,
            KernelOp::LineChange(line) => 12 - 2 * u64::from(*line),
            KernelOp::Complement => 8,
            KernelOp::Matrix(_) => 6,
            KernelOp::Nuclear => 4,
        })
        .collect();
    let mut hexagram = rng.below(64) as u8;
    let mut symbols = Vec::with_capacity(n);
    for _ in 0..n {
        hexagram = if rng.chance(eps) {
            rng.below(64) as u8
        } else {
            ops[rng.weighted(&weights)].apply(hexagram)
        };
        symbols.push(u16::from(hexagram));
    }
    Stream {
        name: "operator-walk".into(),
        kind: Kind::Hexagrams,
        alphabet: 64,
        eps,
        symbols,
        units: n,
    }
}

/// A plain cast walk: the I Ching's own moving-line dynamic, which no single
/// kernel operator describes (several lines move at once).
pub fn casting_walk(n: usize) -> Stream {
    let mut rng = Rng::new(seed("casting-walk", n, 0.0));
    let mut hexagram = rng.below(64) as u8;
    let symbols = (0..n)
        .map(|_| {
            hexagram = cast(&mut rng, hexagram);
            u16::from(hexagram)
        })
        .collect();
    Stream {
        name: "casting-walk".into(),
        kind: Kind::Hexagrams,
        alphabet: 64,
        eps: 0.0,
        symbols,
        units: n,
    }
}

/// QLC-2 source: melodies that stay in one lens's Context-Frame cut for a
/// phrase, stepping mostly by small scale degrees, then move to another lens.
pub fn modal_melody(n: usize, eps: f64) -> Stream {
    let mut rng = Rng::new(seed("modal-melody", n, eps));
    let scales = lens_scales();
    let steps: [i64; 7] = [-3, -2, -1, 0, 1, 2, 3];
    let step_weights = [1, 3, 8, 4, 8, 3, 1];
    let mut symbols = Vec::with_capacity(n);
    let mut lens = rng.below(12) as usize;
    let mut degree = rng.below(7) as i64;
    let mut phrase = 0;
    for _ in 0..n {
        if phrase == 0 {
            lens = rng.below(12) as usize;
            phrase = 32 + rng.below(64);
        }
        phrase -= 1;
        degree = (degree + steps[rng.weighted(&step_weights)]).rem_euclid(7);
        symbols.push(if rng.chance(eps) {
            rng.below(12) as u16
        } else {
            u16::from(scales[lens][degree as usize])
        });
    }
    Stream {
        name: "modal-melody".into(),
        kind: Kind::Pitches,
        alphabet: 12,
        eps,
        symbols,
        units: n,
    }
}

/// Real kernel record: the retained M3 clock's hexagram estimate at each of
/// its 360 degrees (an approximation the kernel keeps as source values).
pub fn recorded_clock() -> Stream {
    let symbols: Vec<u16> = m3_clock::recorded_clock()
        .iter()
        .map(|record| record.field(m3_clock::ClockField::HexagramEstimate) & 0x3F)
        .collect();
    let units = symbols.len();
    Stream {
        name: "recorded-clock".into(),
        kind: Kind::Hexagrams,
        alphabet: 64,
        eps: 0.0,
        symbols,
        units,
    }
}

/// Real text: this repository's top-level docs, sorted and concatenated,
/// capped at `cap` bytes.
pub fn docs_text(repo: &Path, cap: usize) -> Vec<u8> {
    let mut paths: Vec<_> = std::fs::read_dir(repo.join("docs"))
        .expect("docs directory")
        .filter_map(|entry| entry.ok().map(|e| e.path()))
        .filter(|path| path.extension().is_some_and(|ext| ext == "md"))
        .collect();
    paths.sort();
    let mut text = Vec::new();
    for path in paths {
        text.extend(std::fs::read(path).expect("readable doc"));
        if text.len() >= cap {
            break;
        }
    }
    text.truncate(cap - cap % 3);
    text
}

pub fn text_bytes(text: &[u8]) -> Stream {
    Stream {
        name: "docs-text".into(),
        kind: Kind::Bytes,
        alphabet: 256,
        eps: 0.0,
        symbols: text.iter().map(|b| u16::from(*b)).collect(),
        units: text.len(),
    }
}

/// The same text regrouped into 6-bit symbols (3 bytes → 4 sextets), the
/// projection under which a hexagram codec can be applied to any bytes.
pub fn text_sextets(text: &[u8]) -> Stream {
    let mut symbols = Vec::with_capacity(text.len() / 3 * 4);
    for chunk in text.chunks_exact(3) {
        let word = (u32::from(chunk[0]) << 16) | (u32::from(chunk[1]) << 8) | u32::from(chunk[2]);
        for shift in [18, 12, 6, 0] {
            symbols.push(((word >> shift) & 0x3F) as u16);
        }
    }
    Stream {
        name: "docs-text-sextets".into(),
        kind: Kind::Hexagrams,
        alphabet: 64,
        eps: 0.0,
        symbols,
        units: text.len(),
    }
}

/// The MIDI keys of one Ableton clip (`.alc`, already gunzipped) in time
/// order, simultaneous notes lowest first.
pub fn clip_keys(xml: &str) -> Vec<u8> {
    let mut notes: Vec<(f64, u8)> = Vec::new();
    for track in xml.split("<KeyTrack ").skip(1) {
        let track = track.split("</KeyTrack>").next().unwrap_or("");
        let Some(key) = attribute(track.split("<MidiKey ").nth(1).unwrap_or(""), "Value") else {
            continue;
        };
        let Ok(key) = key.parse::<u8>() else {
            continue;
        };
        for event in track.split("<MidiNoteEvent ").skip(1) {
            if let Some(time) = attribute(event, "Time").and_then(|t| t.parse::<f64>().ok()) {
                notes.push((time, key));
            }
        }
    }
    notes.sort_by(|a, b| a.0.total_cmp(&b.0).then(a.1.cmp(&b.1)));
    notes.into_iter().map(|(_, key)| key).collect()
}

fn attribute<'a>(text: &'a str, name: &str) -> Option<&'a str> {
    let start = text.find(&format!("{name}=\""))? + name.len() + 2;
    let end = text[start..].find('"')? + start;
    Some(&text[start..end])
}

/// Real melodies: the pitch classes of a run of clips, one after another.
pub fn clip_pitches(name: &str, keys: &[u8]) -> Stream {
    Stream {
        name: name.into(),
        kind: Kind::Pitches,
        alphabet: 12,
        eps: 0.0,
        symbols: keys.iter().map(|k| u16::from(k % 12)).collect(),
        units: keys.len(),
    }
}
